async function download(c:any,path:string,limit=3_000_000){let size=0;const chunks:Buffer[]=[];const sink=new Writable({write(chunk,_enc,done){size+=chunk.length;if(size>limit)return done(Error("Read limit exceeded"));chunks.push(Buffer.from(chunk));done();}});await c.downloadTo(sink,path);return Buffer.concat(chunks);}
async function connect(){if(!Bun.env.FTP_HOST_PRIMARY||!Bun.env.FTP_USER||!Bun.env.FTP_PASSWORD)throw Error("Existing FTP environment incomplete");const certificateHost="h59.servidorhh.com";const [a,b]=await Promise.all([lookup(Bun.env.FTP_HOST_PRIMARY,{all:true}),lookup(certificateHost,{all:true})]);if(!a.some(x=>b.some(y=>x.address===y.address)))throw Error("Certificate host DNS mismatch");const c=new ftp.Client(30000);await c.access({host:Bun.env.FTP_HOST_PRIMARY,user:Bun.env.FTP_USER,password:Bun.env.FTP_PASSWORD,secure:true,secureOptions:{servername:certificateHost,rejectUnauthorized:true}});return c;}
