const report:any={revision,startedAt:new Date().toISOString(),uploaded:[],reused:[],backups:[],state:"running"};
async function publishRmbh(){
 let c:any;const applied:any[]=[];
 try{
 c=await connect();await c.cd("public_html");const root=await c.pwd();const rootList=await c.list();
 if(!rootList.some((x:any)=>x.name==="index.html"))throw Error("Expected official home not found");
 const home=(await download(c,"index.html")).toString("utf8");if(!/arquindex/i.test(home)||!home.includes("www.arquindex.com.br"))throw Error("Official home validation failed");
 const originals=new Map<string,Buffer|null>();
 async function readOptional(path:string){await c.cd(root);try{return await download(c,path);}catch(e){if((e as any).code===550)return null;throw e;}}
 const changes=new Map<string,Buffer>();
 function insert(html:string,fragment:string){const start="<!-- ARQUINDEX_RMBH_START -->",end="<!-- ARQUINDEX_RMBH_END -->";const a=html.indexOf(start),b=html.indexOf(end);if(a>=0&&b>a)html=html.slice(0,a)+html.slice(b+end.length);const block=start+fragment+end;const anchor=html.includes("</main>")?"</main>":html.includes("<footer")?"<footer":"</body>";if(!html.includes(anchor))throw Error("HTML insertion point unavailable");return html.replace(anchor,block+anchor);}
 for(const city of data.cities.slice(0,3)){
 const previous=await readOptional(city.target);if(!previous)throw Error("Existing city page missing: "+city.target);
 const html=previous.toString("utf8");if(!/arquindex/i.test(html)||!html.includes(city.target))throw Error("City page validation failed: "+city.target);
 originals.set(city.target,previous);changes.set(city.target,Buffer.from(insert(html,data.fragments[city.slug])));
 }
 const generated={"atendimento-rmbh/index.html":data.homehostHub,"atendimento-rmbh/nova-lima.html":data.newNovaLima,"atendimento-rmbh/sitemap.xml":sitemap};
 for(const [path,content]of Object.entries(generated)){originals.set(path,await readOptional(path));changes.set(path,Buffer.from(content as string));}
 const homeFragment='<section class="rmbh-wrap" aria-label="Atendimento na Grande BH"><style>'+data.css+'</style><h2>Projetos documentais na Grande BH</h2><p>Organização, digitalização, OCR e gestão documental para empresas. Conheça as informações para planejar seu projeto em BH, Betim, Contagem e Nova Lima e consulte atendimento para os demais municípios da região.</p><a class="rmbh-cta" href="/atendimento-rmbh/">Conheça o atendimento regional</a></section>';
 originals.set("index.html",Buffer.from(home));changes.set("index.html",Buffer.from(insert(home,homeFragment)));
 const robots=await readOptional("robots.txt");if(!robots)throw Error("Existing robots.txt missing; refusing to replace rules");
 const line="Sitemap: https://www.arquindex.com.br/atendimento-rmbh/sitemap.xml";
 originals.set("robots.txt",robots);changes.set("robots.txt",Buffer.from(robots.toString("utf8").includes(line)?robots:robots.toString("utf8").trimEnd()+"\n"+line+"\n"));
 const backupDir="/backups/"+revision;await mkdir(backupDir,{recursive:true});
 for(const [path,bytes]of changes){
 const previous=originals.get(path);if(previous&&await digest(previous)===await digest(bytes)){report.reused.push(path);continue;}
 if(previous){const bpath=backupDir+"/"+path.replaceAll("/","__")+"."+(await digest(previous)).slice(0,16);await Bun.write(bpath,previous);if(await digest(new Uint8Array(await Bun.file(bpath).arrayBuffer()))!==await digest(previous))throw Error("Backup verification failed");report.backups.push({path,backup:bpath});}
 await c.cd(root);const current=await readOptional(path);if((!!previous)!=(!!current)||(previous&&current&&await digest(previous)!==await digest(current)))throw Error("File changed concurrently: "+path);
 const slash=path.lastIndexOf("/");if(slash>=0){await c.ensureDir(root+"/"+path.slice(0,slash));await c.cd(root);}
 const tmp=path+".upload-"+revision;
 await c.uploadFrom(Readable.from([bytes]),tmp);if(await digest(await download(c,tmp))!==await digest(bytes))throw Error("Upload mismatch: "+path);
 if(previous)await c.remove(path);
 try{await c.rename(tmp,path);}catch(e){if(previous)await c.uploadFrom(Readable.from([previous]),path);throw e;}
 applied.push({path,previous});report.uploaded.push(path);
 }
 c.close();c=null;
 report.checks=[];
 for(const path of ["atendimento-rmbh/",...data.cities.map((x:any)=>x.target),"atendimento-rmbh/sitemap.xml"]){
 const url="https://www.arquindex.com.br/"+path;const r=await fetch(url,{signal:AbortSignal.timeout(30000),headers:{"cache-control":"no-cache"}});const body=await r.text();
 const marker=path.endsWith(".xml")?body.includes("<urlset"):path==="atendimento-rmbh/"?body.includes("Digitalização e gestão documental na Grande BH"):body.includes("O que informar para receber uma proposta");
 report.checks.push({url,status:r.status,contentVerified:marker});if(!r.ok||!marker)throw Error("Public content verification failed: "+path);
 }
 report.state="published";
 const key="a948be82c7824bc989f2c5dd0f071bea";try{const keyUrl="https://www.arquindex.com.br/"+key+".txt";const kr=await fetch(keyUrl,{signal:AbortSignal.timeout(15000)});if(kr.ok&&(await kr.text()).trim()===key){const ix=await fetch("https://api.indexnow.org/indexnow",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({host:"www.arquindex.com.br",key,keyLocation:keyUrl,urlList:report.checks.filter((x:any)=>!x.url.endsWith(".xml")).map((x:any)=>x.url)}),signal:AbortSignal.timeout(20000)});report.indexNow={status:ix.status,accepted:[200,202].includes(ix.status)};}else report.indexNow={accepted:false,reason:"Public key validation failed"};}catch(e){report.indexNow={accepted:false,error:safe(e)};}
 }catch(error){report.state="failed";report.error=safe((error as Error).message);report.rollback=[];
 try{if(!c)c=await connect();await c.cd("public_html");const root=await c.pwd();for(const change of applied.reverse()){await c.cd(root);if(change.previous)await c.uploadFrom(Readable.from([change.previous]),change.path);else await c.remove(change.path);report.rollback.push(change.path);}}catch(e){report.rollbackError=safe(e);}
 }finally{c?.close();report.finishedAt=new Date().toISOString();await Bun.write("/backups/"+revision+"-result.json",JSON.stringify(report));console.log("RMBH_PUBLISH_RESULT "+JSON.stringify(report));}
}
await publishRmbh();
export default {async fetch(req:Request){const url=new URL(req.url);if(url.pathname==="/health")return Response.json({ok:report.state==="published",service:"arquindex-ftp-maintenance",revision,state:report.state,checks:report.checks??[],indexNow:report.indexNow??null});if(url.pathname!=="/probe")return new Response("Not found",{status:404});if(req.headers.get("x-maintenance-key")!==Bun.env.MAINTENANCE_KEY)return new Response("Forbidden",{status:403});try{const c=await connect();try{const pwd=await c.pwd();const entries=await c.list();return Response.json({ok:true,pwd,entries:entries.map((x:any)=>({name:x.name,type:x.type,size:x.size}))});}finally{c.close();}}catch(e){return Response.json({ok:false,error:safe(e)},{status:502});}}};
